/**
 * Property-Based Tests for Organization Schema Validity
 *
 * **Property 1: Organization Schema Validity**
 * **Validates: Requirements 1.1, 1.2, 1.4**
 *
 * For any Organization schema generated by generateOrganizationSchema,
 * the schema SHALL contain valid @context, @type, name, url, and logo properties,
 * and all string values SHALL be properly sanitized.
 */

import { describe, it, expect } from 'vitest';
import * as fc from 'fast-check';
import {
    generateOrganizationSchema,
    sanitizeStructuredData,
    validateStructuredData,
} from './structured-data';
import { ORGANIZATION_CONFIG } from './config';

/**
 * Arbitrary generator for Locale values
 */
const arbitraryLocale = (): fc.Arbitrary<string> => {
    return fc.constantFrom('en', 'ro');
};

describe('Organization Schema Property Tests', () => {
    describe('Property 1: Organization Schema Validity', () => {
        /**
         * **Feature: schema-org-structured-data, Property 1: Organization Schema Validity**
         * **Validates: Requirements 1.1, 1.2, 1.4**
         */
        it('should generate valid Organization schema with required @context and @type', async () => {
            await fc.assert(
                fc.asyncProperty(arbitraryLocale(), async (locale) => {
                    const schema = generateOrganizationSchema(locale);

                    // Requirement 1.1: Organization schema SHALL be included in JSON-LD
                    expect(schema['@context']).toBe('https://schema.org');
                    expect(schema['@type']).toBe('Organization');
                }),
                { numRuns: 100 },
            );
        });

        it('should contain name, url, and logo properties', async () => {
            await fc.assert(
                fc.asyncProperty(arbitraryLocale(), async (locale) => {
                    const schema = generateOrganizationSchema(locale);

                    // Requirement 1.2: SHALL contain name, logo, URL
                    expect(schema.name).toBeDefined();
                    expect(schema.name).toBe(ORGANIZATION_CONFIG.name);
                    expect(schema.url).toBeDefined();
                    expect(schema.url).toBe(ORGANIZATION_CONFIG.url);
                    expect(schema.logo).toBeDefined();
                }),
                { numRuns: 100 },
            );
        });

        it('should have logo as ImageObject with url, width, and height', async () => {
            await fc.assert(
                fc.asyncProperty(arbitraryLocale(), async (locale) => {
                    const schema = generateOrganizationSchema(locale);

                    // Logo should be an ImageObject, not a string
                    expect(schema.logo).toHaveProperty('@type', 'ImageObject');
                    expect(schema.logo).toHaveProperty('url');
                    expect(schema.logo.url).toBe(ORGANIZATION_CONFIG.logo);
                    expect(schema.logo).toHaveProperty('width');
                    expect(schema.logo).toHaveProperty('height');
                    expect(typeof schema.logo.width).toBe('number');
                    expect(typeof schema.logo.height).toBe('number');
                }),
                { numRuns: 100 },
            );
        });

        it('should include sameAs array with social media links', async () => {
            await fc.assert(
                fc.asyncProperty(arbitraryLocale(), async (locale) => {
                    const schema = generateOrganizationSchema(locale);

                    // Requirement 1.4: SHALL include sameAs for social media
                    expect(schema.sameAs).toBeDefined();
                    expect(Array.isArray(schema.sameAs)).toBe(true);
                    expect(schema.sameAs!.length).toBeGreaterThan(0);

                    // All sameAs entries should be valid URLs
                    schema.sameAs!.forEach((url) => {
                        expect(url).toMatch(/^https?:\/\//);
                    });
                }),
                { numRuns: 100 },
            );
        });

        it('should include contactPoint with availableLanguage', async () => {
            await fc.assert(
                fc.asyncProperty(arbitraryLocale(), async (locale) => {
                    const schema = generateOrganizationSchema(locale);

                    // Requirement 1.2: SHALL contain contact info
                    expect(schema.contactPoint).toBeDefined();
                    expect(schema.contactPoint!['@type']).toBe('ContactPoint');
                    expect(schema.contactPoint!.contactType).toBe('customer support');
                    expect(schema.contactPoint!.email).toBeDefined();
                    expect(schema.contactPoint!.availableLanguage).toBeDefined();
                    expect(Array.isArray(schema.contactPoint!.availableLanguage)).toBe(true);
                    expect(schema.contactPoint!.availableLanguage!.length).toBeGreaterThan(0);
                }),
                { numRuns: 100 },
            );
        });

        it('should include foundingDate and alternateName', async () => {
            await fc.assert(
                fc.asyncProperty(arbitraryLocale(), async (locale) => {
                    const schema = generateOrganizationSchema(locale);

                    expect(schema.foundingDate).toBeDefined();
                    expect(schema.foundingDate).toBe(ORGANIZATION_CONFIG.foundingDate);
                    expect(schema.alternateName).toBeDefined();
                    expect(schema.alternateName).toBe(ORGANIZATION_CONFIG.alternateName);
                }),
                { numRuns: 100 },
            );
        });

        it('should pass validation check', async () => {
            await fc.assert(
                fc.asyncProperty(arbitraryLocale(), async (locale) => {
                    const schema = generateOrganizationSchema(locale);

                    // Schema should pass validation
                    expect(validateStructuredData(schema)).toBe(true);
                }),
                { numRuns: 100 },
            );
        });

        it('should be safe after sanitization (no XSS vectors)', async () => {
            await fc.assert(
                fc.asyncProperty(arbitraryLocale(), async (locale) => {
                    const schema = generateOrganizationSchema(locale);
                    const sanitized = sanitizeStructuredData(schema);

                    // Sanitized schema should still be valid
                    expect(validateStructuredData(sanitized)).toBe(true);

                    // Check that no dangerous content exists
                    const jsonString = JSON.stringify(sanitized);
                    expect(jsonString).not.toMatch(/<script/i);
                    expect(jsonString).not.toMatch(/javascript:/i);
                    expect(jsonString).not.toMatch(/on\w+\s*=/i);
                }),
                { numRuns: 100 },
            );
        });

        it('should have locale-specific description', async () => {
            const schemaEn = generateOrganizationSchema('en');
            const schemaRo = generateOrganizationSchema('ro');

            expect(schemaEn.description).toBe('Machine Learning and AI Competition Platform');
            expect(schemaRo.description).toBe(
                'Platformă de competiții de Machine Learning și Inteligență Artificială',
            );
        });
    });
});
